import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 8;
const FONT_DISPLAY = "'GT Walsheim', Inter, sans-serif";
const FONT_BODY = "Inter, sans-serif";

// ---------- Background ----------
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
    {/* Subtle radial vignette for depth */}
    <AbsoluteFill
      style={{
        background: `radial-gradient(70% 50% at 22% 35%, rgba(248,102,6,0.06), transparent 60%)`,
      }}
    />
  </AbsoluteFill>
);

// ---------- Scene 1: Hero ----------
const SceneHero: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const titleIn = springIn(frame, vfps, 10, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 22, "LIQUID");
  const ruleIn = springIn(frame, vfps, 30, "LIQUID");

  const driftY = ambientDrift(frame, 2.5, 110, "hero-title");
  const eyebrowDrift = ambientDrift(frame, 1.2, 140, "hero-eyebrow");

  const titleTx = interpolate(titleIn, [0, 1], [40, 0]);
  const titleSc = interpolate(titleIn, [0, 1], [0.94, 1]);
  const titleBl = interpolate(titleIn, [0, 1], [10, 0]);

  const ruleScale = interpolate(ruleIn, [0, 1], [0, 1]);

  return (
    <AbsoluteFill style={{ fontFamily: FONT_DISPLAY }}>
      <Background />

      {/* Off-center anchored content — left band, mid-vertical */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "30%",
          maxWidth: "78%",
          transform: `translateY(${driftY}px)`,
        }}
      >
        {/* Eyebrow */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 18,
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0])}px translateX(${eyebrowDrift}px))`,
            marginBottom: 36,
            fontFamily: FONT_DISPLAY,
          }}
        >
          <div
            style={{
              width: 56,
              height: 2,
              background: COLORS.orange,
              transformOrigin: "left center",
              transform: `scaleX(${ruleScale})`,
            }}
          />
          <div
            style={{
              fontFamily: FONT_BODY,
              fontSize: 26,
              fontWeight: 600,
              color: COLORS.orange,
              letterSpacing: "0.22em",
              textTransform: "uppercase",
            }}
          >
            Product Launch
          </div>
        </div>

        {/* Hero title */}
        <div
          style={{
            fontFamily: FONT_DISPLAY,
            fontWeight: 600,
            fontSize: 168,
            lineHeight: 0.98,
            letterSpacing: "-0.035em",
            color: COLORS.text,
            opacity: titleIn,
            transform: `translateY(${titleTx}px) scale(${titleSc})`,
            filter: `blur(${titleBl}px)`,
          }}
        >
          Introducing{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `3px solid ${COLORS.orange}`,
              padding: "0 14px",
              borderRadius: 8,
              color: COLORS.text,
              display: "inline-block",
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            Actors v3
          </span>
        </div>

        {/* Version stamp */}
        <div
          style={{
            marginTop: 44,
            fontFamily: "monospace",
            fontSize: 24,
            color: COLORS.textSubtle,
            letterSpacing: "0.16em",
            opacity: interpolate(ruleIn, [0, 1], [0, 1]),
            transform: `translateY(${interpolate(ruleIn, [0, 1], [10, 0])}px)`,
          }}
        >
          v3.0 / shipping now
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ---------- Scene 2: Benefits ----------
const BENEFITS = [
  { label: "Faster cold starts", descriptor: "Sub-second startup, every run" },
  { label: "Native MCP support", descriptor: "Plug into any agent runtime" },
  { label: "Pay per second", descriptor: "Granular billing, zero waste" },
];

const CheckMark: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <path
      d="M5 12.5 L10 17.5 L19 7"
      stroke={COLORS.orange}
      strokeWidth={2.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
      strokeDasharray={28}
      strokeDashoffset={interpolate(progress, [0, 1], [28, 0])}
      opacity={progress}
    />
  </svg>
);

const BenefitRow: React.FC<{
  item: (typeof BENEFITS)[number];
  index: number;
  delay: number;
}> = ({ item, index, delay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const inP = staggeredSpring(frame, vfps, index, delay, 10, "GENTLE");
  const checkP = staggeredSpring(frame, vfps, index, delay + 4, 10, "LIQUID");

  const breathe = ambientDrift(frame, 1, 95 + index * 12, `row-${index}`);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "flex-start",
        gap: 28,
        opacity: inP,
        transform: `translateX(${interpolate(inP, [0, 1], [-30, 0])}px) translateY(${breathe}px)`,
      }}
    >
      <div style={{ marginTop: 8 }}>
        <CheckMark size={48} progress={checkP} />
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        <div
          style={{
            fontFamily: FONT_DISPLAY,
            fontWeight: 600,
            fontSize: 64,
            color: COLORS.text,
            letterSpacing: "-0.015em",
            lineHeight: 1.05,
          }}
        >
          {item.label}
        </div>
        <div
          style={{
            fontFamily: FONT_BODY,
            fontWeight: 400,
            fontSize: 28,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.3,
          }}
        >
          {item.descriptor}
        </div>
      </div>
    </div>
  );
};

const SceneBenefits: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const titleIn = springIn(frame, vfps, 4, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 14, "LIQUID");
  const cardIn = springIn(frame, vfps, 10, "LIQUID");

  const titleDrift = ambientDrift(frame, 1.8, 120, "benefits-title");
  const cardDrift = ambientDrift(frame, 2, 140, "benefits-card");

  return (
    <AbsoluteFill style={{ fontFamily: FONT_DISPLAY }}>
      <Background />

      {/* Asymmetric grid: title top-left, card bottom-right */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "12%",
          maxWidth: "55%",
          opacity: titleIn,
          transform: `translateY(${interpolate(titleIn, [0, 1], [24, 0])}px) translateY(${titleDrift}px)`,
        }}
      >
        <div
          style={{
            fontFamily: FONT_DISPLAY,
            fontWeight: 600,
            fontSize: 88,
            lineHeight: 1.05,
            letterSpacing: "-0.028em",
            color: COLORS.text,
          }}
        >
          Built for{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `2.5px solid ${COLORS.orange}`,
              padding: "0 12px",
              borderRadius: 6,
              display: "inline-block",
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            modern agents
          </span>
        </div>
      </div>

      {/* Benefits card */}
      <div
        style={{
          position: "absolute",
          left: "12%",
          top: "42%",
          width: "76%",
          background: "rgba(255,255,255,0.04)",
          border: `1px solid ${COLORS.border}`,
          borderRadius: 18,
          padding: "56px 64px",
          display: "flex",
          flexDirection: "column",
          gap: 40,
          opacity: cardIn,
          transform: `translateY(${interpolate(cardIn, [0, 1], [32, 0])}px) translateY(${cardDrift}px)`,
          backdropFilter: "blur(8px)",
        }}
      >
        {BENEFITS.map((item, i) => (
          <BenefitRow key={i} item={item} index={i} delay={20} />
        ))}
      </div>
    </AbsoluteFill>
  );
};

// ---------- Scene 3: Sign-off ----------
const SceneSignoff: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const w1 = springIn(frame, vfps, 10, "SNAPPY");
  const w2 = springIn(frame, vfps, 18, "SNAPPY");
  const w3 = springIn(frame, vfps, 26, "SNAPPY");
  const ctaIn = springIn(frame, vfps, 38, "LIQUID");

  const driftY = ambientDrift(frame, 2.2, 130, "signoff-tag");
  const ctaBreathe = ambientDrift(frame, 1.5, 90, "cta-breathe");

  const ctaScale = 1 + ctaBreathe * 0.001;

  const renderWord = (word: string, p: number, accent = false) => {
    const tx = interpolate(p, [0, 1], [30, 0]);
    const sc = interpolate(p, [0, 1], [0.9, 1]);
    const bl = interpolate(p, [0, 1], [8, 0]);
    return (
      <span
        style={{
          display: "inline-block",
          opacity: p,
          transform: `translateY(${tx}px) scale(${sc})`,
          filter: `blur(${bl}px)`,
          color: accent ? COLORS.orange : COLORS.text,
        }}
      >
        {word}
      </span>
    );
  };

  return (
    <AbsoluteFill style={{ fontFamily: FONT_DISPLAY }}>
      <Background />

      {/* Subtle accent shape, top-right parallax */}
      <div
        style={{
          position: "absolute",
          right: "-8%",
          top: "8%",
          width: 520,
          height: 520,
          borderRadius: "50%",
          background: `radial-gradient(closest-side, ${COLORS.orangeTint}, transparent 70%)`,
          filter: "blur(28px)",
          opacity: 0.7,
          transform: `translateX(${ambientDrift(frame, 6, 200, "blob-x")}px) translateY(${ambientDrift(frame, 4, 220, "blob-y")}px)`,
        }}
      />

      {/* Eyebrow */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "26%",
          display: "flex",
          alignItems: "center",
          gap: 18,
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0])}px)`,
          fontFamily: FONT_DISPLAY,
        }}
      >
        <div
          style={{
            width: 48,
            height: 2,
            background: COLORS.orange,
          }}
        />
        <div
          style={{
            fontFamily: FONT_BODY,
            fontSize: 24,
            fontWeight: 600,
            color: COLORS.orange,
            letterSpacing: "0.22em",
            textTransform: "uppercase",
          }}
        >
          Actors v3
        </div>
      </div>

      {/* Big tagline — three words, staggered */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "38%",
          maxWidth: "82%",
          fontFamily: FONT_DISPLAY,
          fontWeight: 600,
          fontSize: 196,
          lineHeight: 0.96,
          letterSpacing: "-0.04em",
          color: COLORS.text,
          transform: `translateY(${driftY}px)`,
          display: "flex",
          flexWrap: "wrap",
          gap: 28,
        }}
      >
        {renderWord("Build.", w1)}
        {renderWord("Run.", w2)}
        {renderWord("Scale.", w3, true)}
      </div>

      {/* CTA pill bottom-left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          bottom: "10%",
          display: "flex",
          alignItems: "center",
          gap: 24,
          opacity: ctaIn,
          transform: `translateY(${interpolate(ctaIn, [0, 1], [16, 0])}px) scale(${ctaScale})`,
        }}
      >
        <div
          style={{
            border: `1.5px solid ${COLORS.orange}`,
            borderRadius: 999,
            padding: "16px 36px",
            fontFamily: FONT_DISPLAY,
            fontSize: 28,
            fontWeight: 600,
            color: COLORS.orange,
            letterSpacing: "-0.005em",
          }}
        >
          Try Actors v3 →
        </div>
        <div
          style={{
            fontFamily: "monospace",
            fontSize: 22,
            color: COLORS.textSubtle,
            letterSpacing: "0.14em",
          }}
        >
          apify.com/actors
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ---------- Composition ----------
const HERO_FRAMES = 70;
const BENEFITS_FRAMES = 80;
const SIGNOFF_FRAMES = 75;

export const durationInFrames =
  HERO_FRAMES + BENEFITS_FRAMES + SIGNOFF_FRAMES - TRANSITION * 2;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={HERO_FRAMES + TRANSITION}>
        <SceneHero />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={BENEFITS_FRAMES + TRANSITION}>
        <SceneBenefits />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SIGNOFF_FRAMES}>
        <SceneSignoff />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
